/* Base */
.np-button,
.np-button-primary,
.np-button[data-variant="default"] {
  --np-button-border: transparent;
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-primary),
    var(--np-foreground) 20%
  );

  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;

  height: 2rem;
  padding: 0 0.625rem;

  border: 1px solid var(--np-button-border);
  border-radius: var(--np-radius-md);

  background: var(--np-primary);
  background-clip: padding-box;
  color: var(--np-primary-foreground);

  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;

  white-space: nowrap;
  text-decoration: none;
  user-select: none;

  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 100ms ease;

  outline: none;
}

.np-button:hover {
  --np-button-hover-bg: color-mix(in oklab, var(--np-primary) 80%, transparent);
  background-color: var(--np-button-hover-bg);
}

.np-button:focus-visible {
  border-color: var(--np-ring);

  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

.np-button:active {
  transform: translateY(1px);
}

button:not(:disabled),
[role="button"]:not(:disabled) {
  cursor: pointer;
}

.np-button[aria-invalid="true"] {
  border-color: var(--np-destructive);

  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

.np-button svg {
  width: 1rem;
  height: 1rem;

  flex-shrink: 0;
  pointer-events: none;
}

.np-button svg:not([class]) {
  width: 1rem;
  height: 1rem;
}

/* Variants */

.np-button-outline,
.np-button[data-variant="outline"] {
  --np-primary: var(--np-background);
  --np-primary-foreground: var(--np-foreground);
  --np-button-border: var(--np-border);

  background-color: var(--np-background);
  color: var(--np-foreground);
}

.np-button-outline:hover,
.np-button[data-variant="outline"]:hover,
.np-button[data-variant="outline"][aria-expanded="true"] {
  background-color: var(--np-muted);
  color: var(--np-foreground);
}

.np-button-secondary,
.np-button[data-variant="secondary"] {
  --np-primary: var(--np-secondary);
  --np-primary-foreground: var(--np-secondary-foreground);

  background-color: var(--np-secondary);
  color: var(--np-secondary-foreground);
}

.np-button-secondary:hover,
.np-button[data-variant="secondary"]:hover {
  background-color: color-mix(
    in oklch,
    var(--np-secondary),
    var(--np-foreground) 5%
  );
}

.np-button-ghost,
.np-button[data-variant="ghost"] {
  --np-primary: transparent;
  --np-primary-foreground: var(--np-foreground);

  background-color: transparent;
  color: var(--np-foreground);
}

.np-button-ghost:hover,
.np-button[data-variant="ghost"]:hover,
.np-button[data-variant="ghost"][aria-expanded="true"] {
  background-color: var(--np-muted);
}

.np-button-destructive,
.np-button[data-variant="destructive"] {
  --np-primary: color-mix(in oklch, var(--np-destructive), transparent 80%);
  --np-primary-foreground: var(--np-destructive);

  background-color: var(--np-primary);
  color: var(--np-primary-foreground);
}

.np-button-destructive:hover,
.np-button[data-variant="destructive"]:hover {
  background-color: color-mix(in oklch, var(--np-destructive), transparent 70%);
}

.np-button-destructive:focus-visible,
.np-button[data-variant="destructive"]:focus-visible {
  border-color: color-mix(in oklch, var(--np-destructive), transparent 50%);

  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

/* Sizes */

.np-button-xs,
.np-button[data-size="xs"] {
  height: 1.5rem;
  gap: 0.25rem;
  padding: 0 0.5rem;
  font-size: 0.75rem;
}

.np-button-sm,
.np-button[data-size="sm"] {
  height: 1.75rem;
  gap: 0.25rem;
  padding: 0 0.625rem;
  font-size: 0.8rem;
}

.np-button-lg,
.np-button[data-size="lg"] {
  height: 2.25rem;
  gap: 0.375rem;
  padding: 0 0.625rem;
}

.np-button-icon,
.np-button[data-size="icon"] {
  width: 2rem;
  height: 2rem;
  padding: 0;
}

.np-button-icon-xs,
.np-button[data-size="icon-xs"] {
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
}

.np-button-icon-sm,
.np-button[data-size="icon-sm"] {
  width: 1.75rem;
  height: 1.75rem;
  padding: 0;
}

.np-button-icon-lg,
.np-button[data-size="icon-lg"] {
  width: 2.25rem;
  height: 2.25rem;
  padding: 0;
}

/* States */

.np-button:disabled,
.np-button[data-state="disabled"] {
  pointer-events: none;
  opacity: 0.5;
}

.np-button[data-state="loading"],
.np-button[data-loading] {
  position: relative;
  pointer-events: none;
  opacity: 0.8;
  cursor: progress;
}

.np-button[data-state="loading"],
.np-button[data-loading]::before {
  content: "";

  width: 1em;
  height: 1em;
  flex-shrink: 0;

  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;

  animation: np-button-spin 0.6s linear infinite;
}

@keyframes np-button-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-button[data-state="loading"],
  .np-button[data-loading]::before {
    animation-duration: 1.2s;
  }
}

/**
 * nepui — design tokens
*/

:root {
  color-scheme: light;

  --np-radius: 0.625rem;
  --np-radius-sm: calc(var(--np-radius) * 0.6);
  --np-radius-md: calc(var(--np-radius) * 0.8);
  --np-radius-lg: var(--np-radius);
  --np-radius-xl: calc(var(--np-radius) * 1.4);
  --np-radius-2xl: calc(var(--np-radius) * 1.8);
  --np-radius-3xl: calc(var(--np-radius) * 2.2);
  --np-radius-4xl: calc(var(--np-radius) * 2.6);
  --np-radius-full: 9999px;

  --np-background: #ffffff;
  --np-foreground: #0a0a0a;

  --np-card: #ffffff;
  --np-card-foreground: #0a0a0a;

  --np-popover: #ffffff;
  --np-popover-foreground: #0a0a0a;

  --np-primary: #111827;
  --np-primary-foreground: #fafafa;

  --np-secondary: #f4f4f5;
  --np-secondary-foreground: #18181b;

  --np-muted: #f4f4f5;
  --np-muted-foreground: #71717a;

  --np-accent: #f4f4f5;
  --np-accent-foreground: #18181b;

  --np-destructive: #fafafa;
  --np-destructive-foreground: #e7000b;

  --np-success: #16a34a;
  --np-success-foreground: #fafafa;

  --np-warning: #d97706;
  --np-warning-foreground: #fafafa;

  --np-border: #e4e4e7;
  --np-input: #e4e4e7;
  --np-ring: #a1a1a1;

  --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --np-shadow-md:
    0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --np-shadow-lg:
    0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
}

/* Explicit dark theme — class or data-attribute toggle (next-themes, etc.) */
.dark,
[data-theme="dark"] {
  color-scheme: dark;

  --np-radius: 0.625rem;
  --np-radius-sm: calc(var(--np-radius) * 0.6);
  --np-radius-md: calc(var(--np-radius) * 0.8);
  --np-radius-lg: var(--np-radius);
  --np-radius-xl: calc(var(--np-radius) * 1.4);
  --np-radius-2xl: calc(var(--np-radius) * 1.8);
  --np-radius-3xl: calc(var(--np-radius) * 2.2);
  --np-radius-4xl: calc(var(--np-radius) * 2.6);
  --np-radius-full: 9999px;

  --np-background: #0a0a0a;
  --np-foreground: #fafafa;

  --np-card: #0a0a0a;
  --np-card-foreground: #fafafa;

  --np-popover: #0a0a0a;
  --np-popover-foreground: #fafafa;

  --np-primary: #fafafa;
  --np-primary-foreground: #18181b;

  --np-secondary: #27272a;
  --np-secondary-foreground: #fafafa;

  --np-muted: #27272a;
  --np-muted-foreground: #a1a1aa;

  --np-accent: #27272a;
  --np-accent-foreground: #fafafa;

  --np-destructive: #fafafa;
  --np-destructive-foreground: #e7000b;

  --np-success: #01a041;
  --np-success-foreground: #f0fdf4;

  --np-warning: #ad4407;
  --np-warning-foreground: #fffbeb;

  --np-border: #27272a;
  --np-input: #27272a;
  --np-ring: #737373;

  --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.4), 0 1px 2px -1px rgb(0 0 0 / 0.4);
  --np-shadow-md:
    0 4px 6px -1px rgb(0 0 0 / 0.4), 0 2px 4px -2px rgb(0 0 0 / 0.4);
  --np-shadow-lg:
    0 10px 15px -3px rgb(0 0 0 / 0.4), 0 4px 6px -4px rgb(0 0 0 / 0.4);
}

/* OS-level dark mode when no explicit theme has been chosen */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]):not(.light) {
    color-scheme: dark;

    --np-radius: 0.625rem;
    --np-radius-sm: calc(var(--np-radius) * 0.6);
    --np-radius-md: calc(var(--np-radius) * 0.8);
    --np-radius-lg: var(--np-radius);
    --np-radius-xl: calc(var(--np-radius) * 1.4);
    --np-radius-2xl: calc(var(--np-radius) * 1.8);
    --np-radius-3xl: calc(var(--np-radius) * 2.2);
    --np-radius-4xl: calc(var(--np-radius) * 2.6);
    --np-radius-full: 9999px;

    --np-background: #0a0a0a;
    --np-foreground: #fafafa;

    --np-card: #0a0a0a;
    --np-card-foreground: #fafafa;

    --np-popover: #0a0a0a;
    --np-popover-foreground: #fafafa;

    --np-primary: #fafafa;
    --np-primary-foreground: #18181b;

    --np-secondary: #27272a;
    --np-secondary-foreground: #fafafa;

    --np-muted: #27272a;
    --np-muted-foreground: #a1a1aa;

    --np-accent: #27272a;
    --np-accent-foreground: #fafafa;

    --np-destructive: #fafafa;
    --np-destructive-foreground: #e7000b;

    --np-success: #01a041;
    --np-success-foreground: #f0fdf4;

    --np-warning: #ad4407;
    --np-warning-foreground: #fffbeb;

    --np-border: #27272a;
    --np-input: #27272a;
    --np-ring: #737373;

    --np-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
    --np-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.4), 0 1px 2px -1px rgb(0 0 0 / 0.4);
    --np-shadow-md:
      0 4px 6px -1px rgb(0 0 0 / 0.4), 0 2px 4px -2px rgb(0 0 0 / 0.4);
    --np-shadow-lg:
      0 10px 15px -3px rgb(0 0 0 / 0.4), 0 4px 6px -4px rgb(0 0 0 / 0.4);
  }
}
